L = []
for code, part, text, leaves in ITEMS:
    for i, t in enumerate(leaves, 1):
        L.append({"leaf": f"{code}/{i}", "item": code, "part": part, "text": t})
json.dump({"items": [{"code": c, "part": p, "text": t} for c, p, t, _ in ITEMS], "leaves": L}, open("data/g1syl/leaves.json", "w"), ensure_ascii=False, indent=1)
with open("data/g1syl/leaves.md", "w") as f:
    f.write("# APPSC Group 1 Prelims syllabus (05-10-2018), as leaves\n\nPaper II Part A (Mental Ability) is left out (the owner's choice).\n")
    cur = None
    for c, p, t, lv in ITEMS:
        if p != cur:
            f.write(f"\n## {p}\n")
            cur = p
        f.write(f"\n**{c}.** {t}\n\n")
        for i, x in enumerate(lv, 1):
            f.write(f"- `{c}/{i}` {x}\n")
print(len(L), "leaves in", len(ITEMS), "items")
